    private func check(_ w: VisibilityWindow, ever: Bool, always: Bool, rise: Date?, set: Date?, maxT: Date, maxAlt: Double, maxAz: Double) {
        #expect(w.risesAboveThreshold == ever)
        #expect(w.alwaysAboveThreshold == always)
        #expect((w.riseTime == nil) == (rise == nil)); if let a = w.riseTime, let b = rise { #expect(abs(a.timeIntervalSince(b)) <= 0.002) }
        #expect((w.setTime == nil) == (set == nil)); if let a = w.setTime, let b = set { #expect(abs(a.timeIntervalSince(b)) <= 0.002) }
        #expect(w.maxAltitudeTime == maxT)
        #expect(abs(w.maxAltitudeDeg - maxAlt) < tol)
        #expect(abs(w.azimuthAtMax - maxAz) < azTol)
    }

