            check(AltitudeSampler.sample(observer: obs, position: { PlanetPositions.geocentricEquatorial(.jupiter, jd: $0) }, start: start, end: end, thresholdDeg: RiseSetThresholds.starOrPlanet),
                  ever: true, always: false, rise: Date(timeIntervalSince1970: 1793633422.296), set: nil,
                  maxT: Date(timeIntervalSince1970: 1793646000), maxAlt: 34.89384724322328, maxAz: 34.29755910905999)  // jupiter
        }
        // Tromso Jun 21 2026 session
        do {
            let obs = Observer(latitudeDeg: 69.6492, longitudeDeg: 18.9553)
            let start = Date(timeIntervalSince1970: 1782057600), end = Date(timeIntervalSince1970: 1782100800)
            check(AltitudeSampler.sample(observer: obs, position: { SunPosition.geocentricEquatorial($0) }, start: start, end: end, thresholdDeg: RiseSetThresholds.sun),
                  ever: true, always: true, rise: nil, set: nil,
                  maxT: Date(timeIntervalSince1970: 1782057600), maxAlt: 25.887706351485473, maxAz: 267.8746354697839)  // sun
            check(AltitudeSampler.sample(observer: obs, position: { MoonPosition.geocentric($0).equatorial }, start: start, end: end, thresholdDeg: RiseSetThresholds.moon(horizontalParallaxDeg: MoonPosition.geocentric(JulianDate.from(start)).horizontalParallaxDeg)),
                  ever: true, always: false, rise: nil, set: Date(timeIntervalSince1970: 1782079996.852),
                  maxT: Date(timeIntervalSince1970: 1782058920), maxAlt: 19.22652569627985, maxAz: 177.2416821997193)  // moon
            check(AltitudeSampler.sample(observer: obs, position: { _ in EquatorialCoordinates(rightAscensionDeg: 83.8221, declinationDeg: -5.3911) }, start: start, end: end, thresholdDeg: RiseSetThresholds.starOrPlanet),
                  ever: false, always: false, rise: nil, set: nil,
                  maxT: Date(timeIntervalSince1970: 1782057600), maxAlt: -3.3189621968128584, maxAz: 263.43843444092437)  // M42
            check(AltitudeSampler.sample(observer: obs, position: { _ in EquatorialCoordinates(rightAscensionDeg: 10.6847, declinationDeg: 41.2690) }, start: start, end: end, thresholdDeg: RiseSetThresholds.starOrPlanet),
                  ever: true, always: true, rise: nil, set: nil,
                  maxT: Date(timeIntervalSince1970: 1782100800), maxAlt: 59.523434889649366, maxAz: 147.3112718365848)  // M31
            check(AltitudeSampler.sample(observer: obs, position: { PlanetPositions.geocentricEquatorial(.jupiter, jd: $0) }, start: start, end: end, thresholdDeg: RiseSetThresholds.starOrPlanet),
                  ever: true, always: true, rise: nil, set: nil,
                  maxT: Date(timeIntervalSince1970: 1782057600), maxAlt: 33.36402487750309, maxAz: 237.25860732898212)  // jupiter
        }
        do {
            let s = AltitudeSampler.series(observer: Observer(latitudeDeg: 41.034, longitudeDeg: -73.7629), position: { _ in EquatorialCoordinates(rightAscensionDeg: 10.6847, declinationDeg: 41.2690) }, start: Date(timeIntervalSince1970: 1793574000), end: Date(timeIntervalSince1970: 1793617620), stepMinutes: 30)
            #expect(s.count == 26)
            #expect(s.last?.time == Date(timeIntervalSince1970: 1793617620))
            #expect(abs((s.last?.altitudeDeg ?? .nan) - 6.640566400480712) < tol)
        }
    }
}
